const plan = $json.output || $json;
const errors = [];

let prepareInput = {};

try {
  prepareInput = $("Prepare Input").first().json;
} catch (error) {
  prepareInput = {};
}

const traceId = $json.trace_id || prepareInput.trace_id || $execution.id;
const userQuestion = $json.user_question || prepareInput.user_question || "";
const sessionId = $json.session_id || prepareInput.session_id || null;
const sourceChannel = $json.source_channel || prepareInput.source_channel || null;

// Normalize required array fields so downstream validation can safely iterate.
if (!Array.isArray(plan.metrics)) {
  plan.metrics = [];
}

if (!Array.isArray(plan.dimensions)) {
  plan.dimensions = [];
}

if (!Array.isArray(plan.filters)) {
  plan.filters = [];
}

// Ensure the date object always has the fields Phase 1 expects.
if (!plan.date_range || typeof plan.date_range !== "object") {
  plan.date_range = {
    start: null,
    end: null,
    date_column: null,
    relative_period: null
  };
}

if (!Object.prototype.hasOwnProperty.call(plan.date_range, "relative_period")) {
  plan.date_range.relative_period = null;
}

const normalizeKey = (value) => {
  if (typeof value !== "string") return value;
  return value.trim().toLowerCase().replace(/\s+/g, "_");
};

// Convert model vocabulary into canonical key format before alias lookup.
// Example: "ROAS" -> "roas", "Return On Ad Spend" -> "return_on_ad_spend".
plan.route = normalizeKey(plan.route);
plan.dataset = normalizeKey(plan.dataset);
plan.analysis_type = normalizeKey(plan.analysis_type);
plan.intent = normalizeKey(plan.intent);

plan.metrics = plan.metrics.map(normalizeKey);
plan.dimensions = plan.dimensions.map(normalizeKey);

plan.filters = plan.filters.map(filter => ({
  ...filter,
  field: normalizeKey(filter.field),
  operator: normalizeKey(filter.operator)
}));

if (plan.date_range.date_column) {
  plan.date_range.date_column = normalizeKey(plan.date_range.date_column);
}

if (plan.date_range.relative_period) {
  plan.date_range.relative_period = normalizeKey(plan.date_range.relative_period);
}

// Use the business catalog when available. If the Planner Agent output dropped it,
// read it from the Add Business Catalog node.
let catalog = $json.business_catalog || {};

if (!catalog.datasets) {
  try {
    catalog = $("Add Business Catalog").first().json.business_catalog || {};
  } catch (error) {
    catalog = {};
  }
}

// Some questions are clearly outside the Phase 1 datasets.
// These should be unsupported, not clarification.
const questionText = String($json.user_question || "").toLowerCase();

const unsupportedTerms = [
  "employee",
  "employees",
  "salary",
  "salaries",
  "payroll",
  "hr",
  "human resources",
  "inventory",
  "stock level",
  "stock levels",
  "support ticket",
  "support tickets",
  "weather",
  "stock price",
  "stock prices"
];

const isClearlyUnsupported = unsupportedTerms.some(term => {
  return questionText.includes(term);
});

// Unsupported must be handled before clarification because unsupported plans
// intentionally use dataset = "unknown" and analysis_type = "unknown".
if (
  isClearlyUnsupported ||
  plan.route === "unsupported" ||
  plan.dataset === "unsupported" ||
  plan.intent === "unsupported" ||
  plan.analysis_type === "unsupported"
) {
  return [{
  json: {
    trace_id: traceId,
    user_question: userQuestion,
    session_id: sessionId,
    source_channel: sourceChannel,
    plan_valid: false,
    route: "unsupported",
    errors: ["Unsupported dataset or question type."],
    plan: {
      ...plan,
      route: "unsupported",
      intent: "unsupported",
      dataset: "unknown",
      analysis_type: "unknown",
      metrics: [],
      dimensions: [],
      filters: [],
      date_range: {
        start: null,
        end: null,
        date_column: "unknown",
        relative_period: null
      },
      limit: 0,
      needs_clarification: false,
      clarification_question: null
    }
  }
}];
}

const datasets = catalog.datasets || {};
const datasetCatalog = datasets[plan.dataset] || {};
const fieldAliases = datasetCatalog.field_aliases || {};
const metricAliases = datasetCatalog.metric_aliases || {};

// Fallback aliases protect the workflow if the catalog is missing from the item
// or the Planner uses common business vocabulary instead of canonical keys.
const fallbackMetricAliases = {
  ecommerce_orders: {
    sales: "net_sales",
    total_sales: "net_sales",
    revenue: "net_sales",
    net_revenue: "net_sales",
    gross_revenue: "gross_sales",
    orders: "order_count",
    order_volume: "order_count",
    number_of_orders: "order_count",
    returns: "return_rate",
    returned_orders: "return_rate",
    rating: "average_rating",
    customer_rating: "average_rating",
    delivery_time: "average_delivery_days",
    shipping_time: "average_delivery_days"
  },
  marketing_campaigns: {
    return_on_ad_spend: "roas",
    return_on_ads_spend: "roas",
    roas: "roas",
    click_through_rate: "ctr",
    c_t_r: "ctr",
    cvr: "conversion_rate",
    conversion_percentage: "conversion_rate",
    conversion_percent: "conversion_rate",
    conversions_rate: "conversion_rate",
    cpc: "cost_per_click",
    cpa: "cost_per_conversion",
    cost_per_acquisition: "cost_per_conversion",
    rpc: "revenue_per_click",
    lead_customer_rate: "lead_to_customer_rate"
  }
};

const fallbackDimensionAliases = {
  marketing_campaigns: {
    platform: "channel",
    ad_platform: "channel",
    marketing_platform: "channel",
    social_platform: "channel",
    marketing_channel: "channel",
    campaign_channel: "channel",
    traffic_channel: "channel",
    traffic_source: "channel",
    ad_channel: "channel",
    source: "channel",
    placement: "channel",
    audience: "audience_segment",
    segment: "audience_segment",
    objective: "campaign_objective",
    status: "campaign_status"
  },
  ecommerce_orders: {
    category: "product_category",
    product_category_name: "product_category",
    product_type: "product_category",
    item_category: "product_category",
    product: "product_name",
    item: "product_name",
    channel: "sales_channel",
    order_channel: "sales_channel",
    purchase_channel: "sales_channel",
    platform: "sales_channel",
    payment: "payment_method",
    status: "order_status",
    location: "region",
    market: "region",
    geography: "region"
  }
};

const fallbackMetricAliasMap = fallbackMetricAliases[plan.dataset] || {};
const fallbackDimensionAliasMap = fallbackDimensionAliases[plan.dataset] || {};

// Canonicalize metrics and dimensions before validation.
// Example: "return_on_ad_spend" -> "roas", "ad_platform" -> "channel".
plan.metrics = plan.metrics.map(metric => {
  return metricAliases[metric] || fallbackMetricAliasMap[metric] || metric;
});

plan.dimensions = plan.dimensions.map(dimension => {
  return fieldAliases[dimension] || fallbackDimensionAliasMap[dimension] || dimension;
});

plan.filters = plan.filters.map(filter => ({
  ...filter,
  field: fieldAliases[filter.field] || fallbackDimensionAliasMap[filter.field] || filter.field
}));

// Phase 1 allowlist. Query builders only receive plans that pass this contract.
const allowed = {
  ecommerce_orders: {
    metrics: [
      "order_count",
      "gross_sales",
      "net_sales",
      "return_rate",
      "average_rating",
      "average_delivery_days"
    ],
    dimensions: [
      "gender",
      "region",
      "country",
      "city",
      "product_category",
      "product_name",
      "sales_channel",
      "payment_method",
      "order_status",
      "age_group"
    ],
    date_column: "order_date"
  },
  marketing_campaigns: {
    metrics: [
      "spend",
      "impressions",
      "clicks",
      "conversions",
      "revenue",
      "leads",
      "new_customers",
      "ctr",
      "conversion_rate",
      "cost_per_click",
      "cost_per_conversion",
      "roas",
      "revenue_per_click",
      "lead_to_customer_rate"
    ],
    dimensions: [
      "campaign_name",
      "channel",
      "region",
      "country",
      "audience_segment",
      "device",
      "campaign_objective",
      "campaign_status"
    ],
    date_column: "campaign_date"
  }
};

// If the Planner picked the wrong dataset, use metric/dimension evidence to
// correct it deterministically before validation.
const metricDatasetMap = {
  order_count: "ecommerce_orders",
  gross_sales: "ecommerce_orders",
  net_sales: "ecommerce_orders",
  return_rate: "ecommerce_orders",
  average_rating: "ecommerce_orders",
  average_delivery_days: "ecommerce_orders",
  spend: "marketing_campaigns",
  impressions: "marketing_campaigns",
  clicks: "marketing_campaigns",
  conversions: "marketing_campaigns",
  revenue: "marketing_campaigns",
  leads: "marketing_campaigns",
  new_customers: "marketing_campaigns",
  ctr: "marketing_campaigns",
  conversion_rate: "marketing_campaigns",
  cost_per_click: "marketing_campaigns",
  cost_per_conversion: "marketing_campaigns",
  roas: "marketing_campaigns",
  revenue_per_click: "marketing_campaigns",
  lead_to_customer_rate: "marketing_campaigns"
};

const dimensionDatasetMap = {
  product_category: "ecommerce_orders",
  product_name: "ecommerce_orders",
  sales_channel: "ecommerce_orders",
  payment_method: "ecommerce_orders",
  order_status: "ecommerce_orders",
  age_group: "ecommerce_orders",
  channel: "marketing_campaigns",
  audience_segment: "marketing_campaigns",
  device: "marketing_campaigns",
  campaign_objective: "marketing_campaigns",
  campaign_status: "marketing_campaigns",
  campaign_name: "marketing_campaigns"
};

const metricDatasetVotes = plan.metrics
  .map(metric => metricDatasetMap[metric])
  .filter(Boolean);

const dimensionDatasetVotes = plan.dimensions
  .map(dimension => dimensionDatasetMap[dimension])
  .filter(Boolean);

const datasetVotes = metricDatasetVotes.concat(dimensionDatasetVotes);

const ecommerceVotes = datasetVotes.filter(dataset => dataset === "ecommerce_orders").length;
const marketingVotes = datasetVotes.filter(dataset => dataset === "marketing_campaigns").length;

if (marketingVotes > ecommerceVotes) {
  plan.dataset = "marketing_campaigns";
  plan.date_range.date_column = "campaign_date";
}

if (ecommerceVotes > marketingVotes) {
  plan.dataset = "ecommerce_orders";
  plan.date_range.date_column = "order_date";
}

// Clarification is for vague but potentially supported questions.
// Unsupported was already handled above.
if (
  plan.route === "clarification" ||
  plan.needs_clarification === true ||
  plan.dataset === "unknown" ||
  plan.analysis_type === "unknown"
) {
  return [{
  json: {
    trace_id: traceId,
    user_question: userQuestion,
    session_id: sessionId,
    source_channel: sourceChannel,
    plan_valid: false,
    route: "clarification",
    errors: [],
    plan
  }
}];
}

const datasetConfig = allowed[plan.dataset];

if (!datasetConfig) {
  errors.push(`Invalid dataset: ${plan.dataset}`);
}

// If the Planner supplied filters but forgot dimensions, infer dimensions from
// valid filter fields. Example: filter product_category = Electronics.
if (datasetConfig) {
  for (const filter of plan.filters) {
    if (
      datasetConfig.dimensions.includes(filter.field) &&
      !plan.dimensions.includes(filter.field)
    ) {
      plan.dimensions.push(filter.field);
    }
  }
}

const metrics = plan.metrics;
const dimensions = plan.dimensions;

for (const metric of metrics) {
  if (datasetConfig && !datasetConfig.metrics.includes(metric)) {
    errors.push(`Metric "${metric}" is not allowed for ${plan.dataset}`);
  }
}

for (const dimension of dimensions) {
  if (datasetConfig && !datasetConfig.dimensions.includes(dimension)) {
    errors.push(`Dimension "${dimension}" is not allowed for ${plan.dataset}`);
  }
}

if (
  datasetConfig &&
  plan.date_range.date_column &&
  plan.date_range.date_column !== datasetConfig.date_column
) {
  errors.push(`Invalid date column for ${plan.dataset}`);
}

const dimensionRequiredTypes = [
  "grouped_metric_ranking",
  "grouped_metric_breakdown",
  "filtered_grouped_breakdown",
  "dimension_comparison"
];

if (
  dimensionRequiredTypes.includes(plan.analysis_type) &&
  dimensions.length === 0
) {
  errors.push(`Analysis type "${plan.analysis_type}" requires at least one dimension.`);
}

return [{
  json: {
    trace_id: traceId,
    user_question: userQuestion,
    session_id: sessionId,
    source_channel: sourceChannel,
    plan_valid: errors.length === 0,
    route: errors.length === 0 ? plan.dataset : "invalid_plan",
    errors,
    plan
  }
}];

