parameters.jsCode:
const input = $input.first().json;

const route = input.route || (input.output ? input.output.route : null);
const plan = input.plan || input.output || {};
const errors = input.errors || [];

const traceId = input.trace_id || $execution.id;
const userQuestion = input.user_question || "";
const sessionId = input.session_id || null;
const sourceChannel = input.source_channel || null;

let response = "";

if (route === "clarification") {
  response =
    plan.clarification_question ||
    "Can you clarify what you would like me to analyze?";
} else if (route === "unsupported") {
  response =
    "I can help with ecommerce orders and marketing campaign analytics. This question looks outside the datasets currently available in Phase 1.";
} else if (route === "invalid_plan") {
  response =
    "I could not create a safe analysis plan for this question. Please ask using a supported ecommerce or marketing metric, such as sales by category, return rate by region, or ROAS by channel.";
} else {
  response =
    "I could not route this request safely. Please try a supported ecommerce or marketing analytics question.";
}

return [{
  json: {
    trace_id: traceId,
    user_question: userQuestion,
    session_id: sessionId,
    source_channel: sourceChannel,
    status: route,
    response,
    route,
    plan,
    errors,
    warnings: errors
  }
}];

function getNodeJson(nodeName) {
  try {
    return $(nodeName).first().json;
  } catch (error) {
    return null;
  }
}

// This node is shared by ecommerce and marketing, so read context from whichever
// query builder ran in this execution.
const queryContext =
  getNodeJson("Build Ecommerce Analytics Query") ||
  getNodeJson("Build Marketing Analytics Query") ||
  {};

const rows = $input.all().map(item => item.json);

const plan = queryContext.plan || {};
const queryMetadata = queryContext.query_metadata || {};

const dataset = queryMetadata.dataset || plan.dataset || "unknown";
const analysisType = queryMetadata.analysis_type || plan.analysis_type || "unknown";

const metrics = Array.isArray(queryMetadata.metrics)
  ? queryMetadata.metrics
  : Array.isArray(plan.metrics)
    ? plan.metrics
    : [];

const dimensions = Array.isArray(queryMetadata.dimensions)
  ? queryMetadata.dimensions
  : Array.isArray(plan.dimensions)
    ? plan.dimensions
    : [];

const primaryMetric = metrics[0] || null;
const primaryDimension = dimensions[0] || null;
const dateRange = plan.date_range || {};

// Ratio metrics can return null when their denominator is zero or missing.
const ratioMetrics = [
  "return_rate",
  "ctr",
  "conversion_rate",
  "cost_per_click",
  "cost_per_conversion",
  "roas",
  "revenue_per_click",
  "lead_to_customer_rate"
];

const requestedValuesFromMetadata = Array.isArray(queryMetadata.requested_filter_values)
  ? queryMetadata.requested_filter_values.map(value => String(value))
  : [];

const requestedValuesFromPlan = Array.isArray(plan.filters)
  ? plan.filters
      .filter(filter => {
        return (
          filter.field === primaryDimension &&
          filter.operator === "equals" &&
          filter.value !== undefined &&
          filter.value !== null &&
          String(filter.value).trim() !== ""
        );
      })
      .map(filter => String(filter.value))
  : [];

const requestedValues = requestedValuesFromMetadata.length
  ? requestedValuesFromMetadata
  : requestedValuesFromPlan;

const noRecordsWarning = requestedValues.length
  ? `No matching records found for: ${requestedValues.join(", ")}`
  : dateRange.start && dateRange.end
    ? `No records were found for the resolved date range: ${dateRange.start} to ${dateRange.end}.`
    : "No records were found for this analysis.";

// Empty results mean the requested filter or dataset slice has no usable data.
if (!rows.length) {
  return [{
    json: {
      trace_id: queryContext.trace_id || null,
      user_question: queryContext.user_question || "",
      plan,
      dataset,
      analysis_type: analysisType,
      metrics,
      dimensions,
      dimension: primaryDimension,
      row_count: 0,
      group_record_count: 0,
      date_start: dateRange.start || null,
      date_end: dateRange.end || null,
      warnings: [noRecordsWarning],
      status: "failed",
      response_type: "controlled_failure",
      results: []
    }
  }];
}

const first = rows[0];

// Metadata-only zero-row results happen when the SQL has no matching base rows.
const hasZeroRows = Number(first.total_row_count || 0) === 0;

if (hasZeroRows) {
  return [{
    json: {
      trace_id: queryContext.trace_id || null,
      user_question: queryContext.user_question || "",
      plan,
      dataset,
      analysis_type: analysisType,
      metrics,
      dimensions,
      dimension: primaryDimension,
      row_count: 0,
      group_record_count: 0,
      date_start: dateRange.start || null,
      date_end: dateRange.end || null,
      warnings: [noRecordsWarning],
      status: "failed",
      response_type: "controlled_failure",
      results: []
    }
  }];
}

const warnings = [];

// For comparison questions, make sure every requested value came back.
// Example: Email exists but Paid Social does not, so we should not answer.
const returnedValues = rows.map(row => String(row.dimension_value));

const missingValues = requestedValues.filter(value => {
  return !returnedValues.includes(String(value));
});

if (missingValues.length) {
  warnings.push(`No matching records found for: ${missingValues.join(", ")}`);
}

// Null metric values usually mean the formula could not be calculated.
const hasNullMetricValue = rows.some(row => {
  return row.metric_value === null || row.metric_value === undefined;
});

if (hasNullMetricValue && ratioMetrics.includes(primaryMetric)) {
  warnings.push(
    `The metric "${primaryMetric}" could not be calculated because the denominator was zero or missing.`
  );
} else if (hasNullMetricValue) {
  warnings.push("The selected metric returned no value.");
}

// Missing dates are not always fatal, but the answer should carry a warning.
const hasMissingDateRange = rows.some(row => {
  return !row.date_start || !row.date_end;
});

if (hasMissingDateRange) {
  warnings.push("The result does not include a complete date range.");
}

const totalRowCount = Number(
  first.total_row_count ||
  rows.reduce((sum, row) => {
    return sum + Number(row.group_record_count || row.record_count || 0);
  }, 0)
);

const groupRecordCount = Number(
  first.group_record_count ||
  first.record_count ||
  0
);

// Critical issues mean the system should not return a normal analytical answer.
const hasMissingComparisonValues =
  analysisType === "dimension_comparison" && missingValues.length > 0;

const hasCriticalDataQualityIssue =
  hasMissingComparisonValues || hasNullMetricValue;

const status = hasCriticalDataQualityIssue
  ? "failed"
  : warnings.length
    ? "success_with_warnings"
    : "success";

const responseType = hasCriticalDataQualityIssue
  ? "controlled_failure"
  : "analytics_result";

return [{
  json: {
    trace_id: queryContext.trace_id || null,
    user_question: queryContext.user_question || "",
    plan,
    dataset,
    analysis_type: analysisType,
    metrics,
    dimensions,
    dimension: primaryDimension,
    row_count: totalRowCount,
    group_record_count: groupRecordCount,
    date_start: first.date_start || null,
    date_end: first.date_end || null,
    warnings,
    status,
    response_type: responseType,
    results: hasCriticalDataQualityIssue ? [] : rows
  }
}];

const cleanDate = (value) => {
  if (value === undefined || value === null) return null;
  if (typeof value === "string") {
    const trimmed = value.trim().toLowerCase();
    if (trimmed === "" || trimmed === "null" || trimmed === "unknown") return null;
  }
  return value;
};

const metrics = Array.isArray($json.metrics)
  ? $json.metrics
  : Array.isArray($json.plan?.metrics)
    ? $json.plan.metrics
    : $json.metric
      ? [$json.metric]
      : $json.metric_key
        ? [$json.metric_key]
        : [];

return [{
  json: {
    ...$json,
    selected_dataset: $json.dataset || $json.plan?.dataset || "unknown",
    metrics,
    date_start: cleanDate($json.date_start),
    date_end: cleanDate($json.date_end),
    warnings: Array.isArray($json.warnings) ? $json.warnings : []
  }
}];

const prepareInput = $("Prepare Input").first().json;

// Adjust this depending on where your Supabase cache row stores the plan.
// Common possibilities: $json.plan, $json.cached_plan, $json.plan_json
const rawCachedPlan =
  $json.plan ||
  $json.cached_plan ||
  $json.plan_json ||
  $json.output ||
  null;

let plan = rawCachedPlan;

if (typeof plan === "string") {
  plan = JSON.parse(plan);
}

if (plan?.plan) {
  plan = plan.plan;
}

if (!plan || typeof plan !== "object") {
  return [{
    json: {
      ...prepareInput,
      plan_valid: false,
      route: "invalid_plan",
      errors: ["Cache hit did not include a usable analysis plan."],
      cache_hit: true,
      plan: null
    }
  }];
}

const route =
  plan.route === "unsupported"
    ? "unsupported"
    : plan.needs_clarification
      ? "clarification"
      : plan.dataset || "invalid_plan";

return [{
  json: {
    ...prepareInput,
    plan_valid: route !== "invalid_plan",
    route,
    errors: [],
    cache_hit: true,
    plan
  }
}];

const question = ($json.user_question || "").trim();

const normalizedQuestion = question
  .toLowerCase()
  .replace(/[^\w\s]/g, "")
  .replace(/\s+/g, " ")
  .trim();

let catalog = $json.business_catalog || {};

if (typeof catalog === "string") {
  try {
    catalog = JSON.parse(catalog);
  } catch (error) {
    catalog = {};
  }
}

const catalogVersion = catalog.catalog_version || "unknown_catalog";
const questionHash = `${catalogVersion}:${normalizedQuestion}`;

return [{
  json: {
    ...$json,
    business_catalog: catalog,
    normalized_question: normalizedQuestion,
    catalog_version: catalogVersion,
    question_hash: questionHash
  }
}];

const original = $("Normalize Question For Cache").first().json;

return [{
  json: {
    ...original,

    cache_hit: $json.cache_hit === true,
    cached_plan: $json.plan || null,
    cached_route: $json.route || null,
    cached_dataset: $json.dataset || null,
    cached_analysis_type: $json.analysis_type || null,
    cached_metrics: Array.isArray($json.metrics) ? $json.metrics : [],
    cached_dimensions: Array.isArray($json.dimensions) ? $json.dimensions : [],
    cached_hit_count: Number($json.hit_count || 0)
  }
}];

const validatedPlanPayload = $("Validate Analysis Plan").first().json;

return [{
  json: {
    ...validatedPlanPayload,
    cache_saved: true
  }
}];

const cachedPlanPayload = $("Build Plan From Cache").first().json;

return [{
  json: {
    ...cachedPlanPayload,
    cache_hit_count_updated: true
  }
}];

// Read the validated plan + fetched metric definition from the previous merge node.
const input = $input.first().json;
const metricDefinition = input.metric_definition;
const prepareInput = $("Prepare Input").first().json;

// Pull the normalized analysis plan into local variables.
const plan = input.plan || {};
const dataset = plan.dataset;
const analysisType = plan.analysis_type;
const metrics = plan.metrics || [];
const dimensions = plan.dimensions || [];
const filters = plan.filters || [];
const limit = Number(plan.limit || 0);

// Return a controlled failure payload instead of allowing Postgres to run bad SQL.
function fail(message) {
  return [{
    json: {
      ...input,
      route: "invalid_plan",
      query_status: "failed",
      errors: [...(input.errors || []), message]
    }
  }];
}

// The metric formula must come from metric_registry.
if (!metricDefinition?.formula) {
  return fail(`No metric definition was found for ${dataset}.${metrics[0] || "unknown"}`);
}

// This builder is intentionally dataset-specific for Phase 1.
